#!/usr/bin/env python3\nimport sys\nsys.path.insert(0, '/home/tbaltzakis/cloudless.gr')\n\n# Import and test the function directly\nimport re\nfrom collections import defaultdict\n\ndef find_duplicate_packages(filepath='pnpm-lock.yaml'):\n \"\"\"Find duplicate packages in pnpm-lock.yaml\"\"\"\n \n with open(filepath, 'r') as f:\n lines = f.readlines()\n\n # Pattern to match package names in pnpm-lock.yaml format\n package_pattern = re.compile(r'^([a-zA-Z0-9@/\\-_\\.]+):\\s*$')\n\n duplicates = defaultdict(list)\n\n for line_num, line in enumerate(lines, 1):\n line = line.rstrip()\n\n # Skip empty lines and known section headers\n if not line or line in ['dependencies:', 'devDependencies:', 'overrides:', 'settings:', 'importers:', 'lockfileVersion:']:\n continue\n\n # Check if this is a package name line\n match = package_pattern.match(line)\n if match:\n # Extract package name\n package_name = match.group(1)\n\n # Add to duplicates tracking\n duplicates[package_name].append({\n 'line': line_num,\n 'content': line\n })\n\n # Filter to only show actual duplicates\n actual_duplicates = {pkg: occurrences for pkg, occurrences in duplicates.items() if len(occurrences) > 1}\n\n return actual_duplicates, len(duplicates)\n\n# Run the test\nprint(\"=\" * 80)\nprint(\"Testing duplicate package finder\")\nprint(\"=\" * 80)\n\ndups, total = find_duplicate_packages()\nprint(f\"Total packages found: {total}\")\nprint(f\"Duplicate packages: {len(dups)}\")\n\nif dups:\n print(f\"\\n❌ Found {len(dups)} duplicate packages:\\n\")\n for package_name, occurrences in sorted(dups.items()):\n print(f\"📦 Package: {package_name}\")\n print(f\" Occurrences: {len(occurrences)}\")\n for occ in occurrences:\n print(f\" - Line {occ['line']}: {occ['content']}\")\n print()\nelse:\n print(\"✅ No duplicate packages found!\")\n
